async function syncCatalogFromERP() {
  // Simulate sync from upstream ERP/PIM (pricing, inventory, availability)
  await new Promise((resolve) => setTimeout(resolve, 50));
  revalidateTag('products');
}

export default async function AdminCatalogPage() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    'use server';
    after(syncCatalogFromERP);
  }

  return (
    <div style={{ padding: '2rem', maxWidth: 960, margin: '0 auto' }}>
      <header
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: '1.5rem',
          flexWrap: 'wrap',
          gap: '1rem',
        }}
      >
        <h1 style={{ margin: 0, fontSize: '1.5rem' }}>Product Catalog</h1>
        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              background: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: 6,
              cursor: 'pointer',
              fontWeight: 500,
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </header>

      <p
        style={{
          color: '#666',
          marginBottom: '1.5rem',
          fontSize: '0.875rem',
        }}
      >
        Catalog data is cached for fast browsing. Use &quot;Sync latest
        catalog&quot; when upstream ERP/PIM data changes. Sync runs in the
        background—you can continue working immediately.
      </p>

      <table
        style={{
          width: '100%',
          borderCollapse: 'collapse',
          fontSize: '0.875rem',
        }}
      >
        <thead>
          <tr style={{ borderBottom: '2px solid #e5e7eb' }}>
            <th
              style={{
                textAlign: 'left',
                padding: '0.75rem',
                fontWeight: 600,
              }}
            >
              ID
            </th>
            <th
              style={{
                textAlign: 'left',
                padding: '0.75rem',
                fontWeight: 600,
              }}
            >
              Name
            </th>
            <th
              style={{
                textAlign: 'right',
                padding: '0.75rem',
                fontWeight: 600,
              }}
            >
              Price
            </th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr
              key={product.id}
              style={{ borderBottom: '1px solid #e5e7eb' }}
            >
              <td style={{ padding: '0.75rem' }}>{product.id}</td>
              <td style={{ padding: '0.75rem' }}>{product.name}</td>
              <td style={{ padding: '0.75rem', textAlign: 'right' }}>
                ${product.price}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

